<?php
declare(strict_types=1);
require_once __DIR__.'/../../includes/lacms_deadline_helpers.php';
requireLacmsPermission('lacms.deadlines.view');
$pdo=db();$id=(int)($_GET['id']??0);$d=lacmsDeadlineContext($pdo,$id);if(!$d)exit('Deadline not found.');
$a=$pdo->prepare("SELECT a.*,u.full_name user_name,o.name office_name,c.name committee_name FROM lacms_deadline_assignments a LEFT JOIN users u ON u.id=a.user_id LEFT JOIN offices o ON o.id=a.office_id LEFT JOIN committees c ON c.id=a.committee_id WHERE a.deadline_id=:id ORDER BY a.assigned_at");$a->execute([':id'=>$id]);$assign=$a->fetchAll();
?>
<!doctype html><html><head><meta charset="utf-8"><title><?= e($d['deadline_reference']) ?></title><style>body{font:12px Arial;margin:28px;color:#111827}.head{text-align:center;border-bottom:3px solid #0f2137;padding-bottom:12px;margin-bottom:15px}.box{border:1px solid #ccc;padding:9px;margin:8px 0}table{width:100%;border-collapse:collapse;margin-top:12px}th,td{border:1px solid #ccc;padding:6px}th{background:#eee}</style></head><body onload="window.print()"><div class="head"><strong><?= e(APP_NAME) ?></strong><h2>Legislative Deadline Record</h2><div><?= e($d['deadline_reference']) ?></div></div><h3><?= e($d['title']) ?></h3><div class="box"><strong>Due:</strong> <?= formatDateTime($d['due_datetime']) ?><br><strong>Type:</strong> <?= e($d['deadline_type']) ?><br><strong>Priority:</strong> <?= e($d['priority_level']) ?><br><strong>Status:</strong> <?= e($d['status']) ?><br><strong>Responsible:</strong> <?= e($d['responsible_name']?:'—') ?><br><strong>Office:</strong> <?= e($d['office_name']?:'—') ?><br><strong>Committee:</strong> <?= e($d['committee_name']?:'—') ?><br><strong>Context:</strong> <?= e($d['legislative_reference']?:$d['agenda_reference']?:$d['event_reference']?:$d['meeting_reference']?:'General') ?><?php if($d['description']): ?><br><br><?= nl2br(e($d['description'])) ?><?php endif; ?></div><h3>Assignments</h3><table><thead><tr><th>Assignee</th><th>Role</th><th>Status</th></tr></thead><tbody><?php foreach($assign as $x): ?><tr><td><?= e($x['user_name']?:$x['office_name']?:$x['committee_name']?:'—') ?></td><td><?= e($x['assignment_role']) ?></td><td><?= e($x['status']) ?></td></tr><?php endforeach; ?></tbody></table></body></html>
